"""Voice tests: real Whisper on speech generated by macOS `say`."""
import shutil
import subprocess

import numpy as np
import pytest
from fastapi.testclient import TestClient

from app import voice
from app.server import app

if not (voice.MODEL_DIR.exists() and any(voice.MODEL_DIR.iterdir())):
    pytest.skip("whisper model not downloaded", allow_module_level=True)
if not shutil.which("say"):
    pytest.skip("needs macOS `say`", allow_module_level=True)

client = TestClient(app)


@pytest.fixture(scope="module")
def speech_wav(tmp_path_factory):
    path = tmp_path_factory.mktemp("voice") / "speech.wav"
    subprocess.run(["say", "-o", str(path), "--data-format=LEI16@16000",
                    "Add buy milk to my shopping list."], check=True)
    return path.read_bytes()


def words(text):
    return text.lower().replace(".", "").replace(",", "").split()


def test_transcribe_file_bytes(speech_wav):
    text = voice.transcribe(speech_wav)
    assert {"milk", "shopping"} <= set(words(text))  # "buy" can come out as "by"


def test_transcribe_array_and_silence(speech_wav):
    arr = voice.decode(speech_wav)
    assert arr.dtype == np.float32 and 1.0 < len(arr) / voice.SAMPLE_RATE < 6
    assert "milk" in words(voice.transcribe(arr))
    assert voice.transcribe(np.zeros(voice.SAMPLE_RATE * 2, dtype=np.float32)) == ""
    assert voice.transcribe(np.zeros(100, dtype=np.float32)) == ""


def test_transcribe_endpoint(speech_wav):
    r = client.post("/api/voice/transcribe", content=speech_wav, headers={"Content-Type": "audio/wav"})
    assert r.status_code == 200 and "milk" in words(r.json()["text"])
    bad = client.post("/api/voice/transcribe", content=b"x" * 500, headers={"Content-Type": "audio/webm"})
    assert bad.status_code == 400
    assert client.get("/api/voice/status").json()["model"] == "base.en"


def test_desktop_bridge_with_fake_recorder(speech_wav):
    import desktop

    class FakeRecorder:
        def start(self): pass
        def stop(self): return voice.decode(speech_wav)

    bridge = desktop.NativeBridge()
    bridge.recorder = FakeRecorder()
    assert bridge.start_recording() == {"ok": True}
    out = bridge.stop_recording()
    assert out["ok"] and "milk" in words(out["text"])


def test_desktop_bridge_reports_mic_errors():
    import desktop

    class BrokenRecorder:
        def start(self): raise RuntimeError("no input device")

    bridge = desktop.NativeBridge()
    bridge.recorder = BrokenRecorder()
    r = bridge.start_recording()
    assert r["ok"] is False and "no input device" in r["error"]
